import com.swiftcryptollc.crypto.provider.*;
import com.swiftcryptollc.crypto.provider.kyber.KyberParams;

import javax.crypto.KeyAgreement;
import java.security.*;
import java.util.Arrays;
import java.util.HexFormat;

import static com.swiftcryptollc.crypto.provider.kyber.Indcpa.generateKyberKeys;
import static com.swiftcryptollc.crypto.provider.kyber.Indcpa.generateUniform;
import static com.swiftcryptollc.crypto.provider.kyber.Poly.*;

public class Main {
    public static void main(String[] args) throws NoSuchAlgorithmException, InvalidKeyException {
        Security.setProperty("crypto.policy", "unlimited");
        Security.addProvider(new KyberJCE());

        // KEM scheme:
        // A generates keypair
        // A shares her public key to B
        // B generates shared secret
        // B encrypts generated ss using A's public key
        // B sends this ct to A
        // A uses her private key to decrypt ct and to obtain ss with B

        // Excepted values
        String hexSeed = "061550234D158C5EC95595FE04EF7A25767F2E24CC2BC479D09D86DC9ABCFDE7056A8C266F9EF97ED08541DBD2E1FFA1";
        String hexAPk = "";
        String hexASk = "";
        byte[] seed = HexFormat.of().parseHex(hexSeed);
        byte[] expectedAPk = HexFormat.of().parseHex(hexAPk);
        byte[] expectedASk = HexFormat.of().parseHex(hexASk);

        // Alice generates a KeyPair and sends her public key to Bob
        KeyPairGenerator aliceKeyGen = KeyPairGenerator.getInstance("Kyber1024");
        aliceKeyGen.initialize(1024, new SecureRandom(seed));
        KeyPair aliceKeyPair = aliceKeyGen.generateKeyPair();

        // Check generated values against expected values
        byte[] aPk = aliceKeyPair.getPublic().getEncoded();
        byte[] aSk = aliceKeyPair.getPrivate().getEncoded();

        if (!Arrays.equals(aPk, expectedAPk)) {
            System.out.println("Public key does not match!");
        }
        if (!Arrays.equals(aSk, expectedASk)) {
            System.out.println("Secret key does not match!");
        }

        System.out.println("KAT test finished!");
    }
}